// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class ValueStoreFormatTest {

	@Test
	void legacyIdsUseTheLowTwoBits() {
		ValueStoreFormat format = ValueStoreFormat.LEGACY_5_3;

		assertEquals(0xA8L, format.createId((byte) 0, 42));
		assertEquals(0xA9L, format.createId((byte) 1, 42));
		assertEquals(0xAAL, format.createId((byte) 2, 42));
		assertEquals(0xABL, format.createId((byte) 3, 42));
		assertEquals(42, format.getValue(0xA9L));

		assertEquals(ValueStoreFormat.IdKind.IRI, format.getKind(0xA8L));
		assertEquals(ValueStoreFormat.IdKind.LITERAL, format.getKind(0xA9L));
		assertEquals(ValueStoreFormat.IdKind.BNODE, format.getKind(0xAAL));
		assertEquals(ValueStoreFormat.IdKind.INTERNAL, format.getKind(0xABL));
		assertFalse(format.isInlined(0xA9L));
	}

	@Test
	void currentIdsRetainTheExtensibleEncoding() {
		ValueStoreFormat format = ValueStoreFormat.CURRENT;
		long iri = format.createId((byte) 0, 42);
		long literal = format.createId((byte) 1, 42);

		assertEquals((42L << 7) | (ValueIds.T_URI << 1), iri);
		assertEquals((42L << 7) | (ValueIds.T_LITERAL << 1), literal);
		assertEquals(42, format.getValue(iri));
		assertEquals(ValueStoreFormat.IdKind.IRI, format.getKind(iri));
		assertEquals(ValueStoreFormat.IdKind.LITERAL, format.getKind(literal));
	}

	@Test
	void currentInlineValuesAreAlwaysLiterals() {
		long inlineBoolean = ValueIds.createId(ValueIds.T_BOOLEAN, 1);
		assertTrue(ValueStoreFormat.CURRENT.isInlined(inlineBoolean));
		assertTrue(ValueStoreFormat.CURRENT.isLiteral(inlineBoolean));
		assertFalse(ValueStoreFormat.LEGACY_5_3.isInlined(inlineBoolean));
	}

	@Test
	void keyPrefixesMatchTheirOnDiskFormats() {
		assertEquals(3, ValueStoreFormat.LEGACY_5_3.namespaceValue());
		assertEquals(4, ValueStoreFormat.LEGACY_5_3.idKey());
		assertEquals(5, ValueStoreFormat.LEGACY_5_3.hashKey());
		assertEquals(6, ValueStoreFormat.LEGACY_5_3.hashIdKey());

		assertEquals(4, ValueStoreFormat.CURRENT.namespaceValue());
		assertEquals(5, ValueStoreFormat.CURRENT.idKey());
		assertEquals(6, ValueStoreFormat.CURRENT.hashKey());
		assertEquals(7, ValueStoreFormat.CURRENT.hashIdKey());
	}
}
